window.__finlexDocLoaded(10162,{"id":10162,"articles":[{"id":1000679,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Modernized overarching PCAOB standard (replacing legacy AS 1001/1005/1010/1015) establishing the auditor's fundamental obligation to protect investors through independent, objective, and professionally skeptical audits of SEC issuers and broker-dealers.","seq":0},{"id":1000680,"no":"AS 1000.01–.20","heading":"Investor Protection Obligation, Independence & 14-Day Documentation Cutoff","text":"• Fundamental Obligation (AS 1000.01): Protects investors through informative, accurate, and independent auditor's reports — transcending the auditor's relationship with management and the audit committee.\n• Independence & Due Care (AS 1000.04–.12): Independent in fact and appearance (SEC Rule 2-01 + PCAOB ethics rules); exercise professional skepticism and objectively evaluate both corroborating and contradictory evidence.\n• Modernized Engagement Mechanics: Clarifies engagement partner responsibility for review and accelerates the audit documentation assembly window under AS 1215 from 45 days to 14 days (for large firms).","seq":1},{"id":1000681,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Parallel to ISA 200 and China's CSA 1101, but explicitly frames investor protection as the auditor's overriding duty under the Sarbanes-Oxley Act and applies to integrated FS + ICFR audits.","seq":2},{"id":1000682,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (PCAOB Auditing Standards): https://pcaobus.org/oversight/standards/auditing-standards\nStatus: in_force.","seq":3}]});
